-- Run as postgres in one transaction. Creates two NOLOGIN roles and two schemas; touches nothing in public, storage or cron.
\set ON_ERROR_STOP on
begin;
set local lock_timeout = '5s';
do $$ begin
  if exists (select from pg_roles where rolname in ('blsh_replay_owner', 'blsh_replay_api'))
     or exists (select from pg_namespace where nspname in ('blsh_replay', 'blsh_replay_api')) then
    raise exception 'blsh_replay_already_installed';
  end if;
end $$;
create role blsh_replay_owner nologin noinherit;
create role blsh_replay_api nologin noinherit;
alter role blsh_replay_api set statement_timeout = '20s';
alter role blsh_replay_api set timezone = 'UTC';
grant blsh_replay_api to authenticator;
grant blsh_replay_owner to postgres;
create schema blsh_replay authorization blsh_replay_owner;
create schema blsh_replay_api authorization blsh_replay_owner;
revoke all on schema blsh_replay, blsh_replay_api from public;
set local role blsh_replay_owner;

-- Sandbox storage: same columns the BLSH functions read (bucket_id, name, metadata.size), plus the bytes.
create table blsh_replay.storage_buckets (id text primary key, name text not null, public boolean, file_size_limit bigint, allowed_mime_types text[]);
create table blsh_replay.storage_objects (bucket_id text not null references blsh_replay.storage_buckets(id), name text not null, metadata jsonb not null,
  bytes bytea not null, created_at timestamptz not null default clock_timestamp(), primary key (bucket_id, name));

-- ===== 20261116000000_blsh_native_capture_v6.sql (retargeted) =====
-- BLSH native-input capture v6 (tasks/artifacts/blsh-cron-v6-2026-11-15/DESIGN.md §3, §7, §8).
-- FILE ONLY: drafted offline, never applied by the drafting lane. Applying it needs TJ's approval.
-- Inert after apply: blsh_capture_control.enabled defaults to false and no schedule is created here
-- (the pg_cron jobs live in tasks/artifacts/blsh-cron-v6-2026-11-15/schedule/SCHEDULE.sql).
--
-- What it creates:
--   - blsh_capture_control: singleton kill switch (default off);
--   - blsh_capture_runs: one row per (pipeline, source_date), the one-shot claim and state machine;
--   - blsh_capture_objects: append-only sha256 index of every packet file in Storage;
--   - private Storage bucket blsh-native-packets (no policies: service_role only);
--   - service_role-only RPCs used by the route's isolated writer and the watchdog;
--   - owner-only retention helpers: rows are kept forever; Storage bytes are deleted first through the
--     Storage API, and only then is the run marked pruned (DESIGN.md §3.5, review L5).

create table blsh_replay.blsh_capture_control (
  singleton boolean primary key default true check (singleton),
  enabled boolean not null default false,
  updated_at timestamptz not null default now()
);
insert into blsh_replay.blsh_capture_control (singleton) values (true);

create table blsh_replay.blsh_capture_runs (
  run_id uuid primary key default gen_random_uuid(),
  pipeline text not null check (pipeline = 'native-v6'),
  source_date date not null,
  state text not null default 'claimed'
    check (state in ('claimed', 'no_slate', 'refused_schedule', 'failed', 'abandoned_uncertain', 'packet_complete_pending_review')),
  reason text check (reason is null or reason ~ '^[a-z][a-z0-9_:]{2,100}$'),
  claimed_at timestamptz not null default clock_timestamp(),
  closed_at timestamptz,
  deployment jsonb not null default '{}'::jsonb check (jsonb_typeof(deployment) = 'object' and octet_length(deployment::text) <= 2048),
  operation_intents jsonb not null default '[]'::jsonb check (jsonb_typeof(operation_intents) = 'array' and jsonb_array_length(operation_intents) <= 2),
  manifest_sha256 text check (manifest_sha256 ~ '^[0-9a-f]{64}$'),
  keep boolean not null default false,
  pruned_at timestamptz,
  constraint blsh_capture_runs_one_shot unique (pipeline, source_date),
  constraint blsh_capture_runs_closed check ((state = 'claimed') = (closed_at is null)),
  constraint blsh_capture_runs_manifest check ((state in ('packet_complete_pending_review', 'no_slate')) = (manifest_sha256 is not null))
);

create table blsh_replay.blsh_capture_objects (
  run_id uuid not null references blsh_replay.blsh_capture_runs (run_id),
  ordinal integer not null check (ordinal between 1 and 64),
  path text not null unique check (path ~ '^native-v6/\d{4}-\d{2}-\d{2}/[0-9a-f-]{36}/[A-Za-z0-9][A-Za-z0-9._-]{0,127}$'),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  bytes integer not null check (bytes between 1 and 2621440),
  written_at timestamptz not null default clock_timestamp(),
  primary key (run_id, ordinal)
);

alter table blsh_replay.blsh_capture_control enable row level security;
alter table blsh_replay.blsh_capture_runs enable row level security;
alter table blsh_replay.blsh_capture_objects enable row level security;
-- Explicit, whatever the default privileges: service_role may only read; every write goes through
-- the RPCs below, so their checks cannot be bypassed over REST.
revoke all on blsh_replay.blsh_capture_control, blsh_replay.blsh_capture_runs, blsh_replay.blsh_capture_objects from public, anon, authenticated;


-- Rows are never deleted: object rows stay as the integrity record even after their bytes are pruned.
create function blsh_replay.blsh_capture_guard_v1() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise exception 'BLSH capture rows are append-only'; end if;
  if tg_table_name = 'blsh_capture_objects' then raise exception 'BLSH capture objects are append-only'; end if;
  -- blsh_capture_runs: identity never changes; a terminal row is immutable except keep false -> true
  -- and pruned_at null -> a time (only on a closed, not-kept run).
  if new.run_id <> old.run_id or new.pipeline <> old.pipeline or new.source_date <> old.source_date
    or new.claimed_at <> old.claimed_at or new.deployment <> old.deployment then
    raise exception 'BLSH capture run identity is immutable';
  end if;
  if old.state <> 'claimed' then
    if (new.state, new.reason, new.closed_at, new.manifest_sha256, new.operation_intents)
       is distinct from (old.state, old.reason, old.closed_at, old.manifest_sha256, old.operation_intents)
       or (old.keep and not new.keep)
       or (old.pruned_at is not null and new.pruned_at is distinct from old.pruned_at)
       or (new.pruned_at is not null and new.keep) then
      raise exception 'BLSH capture run is terminal';
    end if;
    return new;
  end if;
  if new.pruned_at is not null then raise exception 'BLSH capture run is not closed'; end if;
  if not (new.operation_intents @> old.operation_intents)
     or jsonb_array_length(new.operation_intents) not in (jsonb_array_length(old.operation_intents), jsonb_array_length(old.operation_intents) + 1) then
    raise exception 'BLSH capture intents are append-only';
  end if;
  return new;
end $$;
create trigger blsh_capture_runs_guard before update or delete on blsh_replay.blsh_capture_runs
  for each row execute function blsh_replay.blsh_capture_guard_v1();
create trigger blsh_capture_objects_guard before update or delete on blsh_replay.blsh_capture_objects
  for each row execute function blsh_replay.blsh_capture_guard_v1();

insert into blsh_replay.storage_buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('blsh-native-packets', 'blsh-native-packets', false, 2621440, array['application/json', 'text/html'])
on conflict (id) do nothing;
-- An existing bucket keeps its own settings under "do nothing": refuse unless they are exactly these (review L6).
do $$
begin
  if not exists (select 1 from blsh_replay.storage_buckets as b where b.id = 'blsh-native-packets' and b.public = false
                 and b.file_size_limit = 2621440 and b.allowed_mime_types = array['application/json', 'text/html']::text[]) then
    raise exception 'blsh-native-packets bucket exists with other settings (public, size or MIME limits)';
  end if;
end $$;

create function blsh_replay.blsh_capture_enabled_v1() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select c.enabled from blsh_replay.blsh_capture_control as c where c.singleton), false)
$$;

-- The one-shot claim. A second claim for the same (pipeline, source_date) returns claimed=false.
create function blsh_replay.blsh_capture_claim_v1(p_pipeline text, p_source_date date, p_deployment jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_run uuid;
begin
  if not blsh_replay.blsh_capture_enabled_v1() then raise exception 'BLSH capture is disabled'; end if;
  insert into blsh_replay.blsh_capture_runs (pipeline, source_date, deployment)
  values (p_pipeline, p_source_date, coalesce(p_deployment, '{}'::jsonb))
  on conflict on constraint blsh_capture_runs_one_shot do nothing
  returning run_id into v_run;
  if v_run is null then return pg_catalog.jsonb_build_object('claimed', false); end if;
  return pg_catalog.jsonb_build_object('claimed', true, 'run_id', v_run);
end $$;

-- One intent row before each admission+NST pair (outside the 1000 ms permit window).
create function blsh_replay.blsh_capture_intent_v1(p_run_id uuid, p_group text, p_operations text[])
returns boolean language plpgsql security definer set search_path = '' as $$
declare v_intents jsonb;
begin
  if p_group not in ('individual', 'onIce') or p_operations is distinct from array['admission:' || p_group, 'nst:' || p_group] then
    raise exception 'BLSH capture intent is invalid';
  end if;
  select r.operation_intents into v_intents from blsh_replay.blsh_capture_runs as r where r.run_id = p_run_id and r.state = 'claimed' for update;
  if v_intents is null then raise exception 'BLSH capture run is not claimed'; end if;
  if pg_catalog.jsonb_array_length(v_intents) <> (case p_group when 'individual' then 0 else 1 end) then
    raise exception 'BLSH capture intent is out of order';
  end if;
  update blsh_replay.blsh_capture_runs set operation_intents = v_intents || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
    'group', p_group, 'operations', pg_catalog.to_jsonb(p_operations), 'intendedAtUTC', pg_catalog.clock_timestamp()))
  where run_id = p_run_id;
  return true;
end $$;

-- Records one uploaded Storage object. The path is re-derived from the run row, ordinals are
-- contiguous, and the object must already exist in the bucket with the stated size.
create function blsh_replay.blsh_capture_object_v1(p_run_id uuid, p_ordinal integer, p_path text, p_sha256 text, p_bytes integer)
returns boolean language plpgsql security definer set search_path = '' as $$
declare v_run blsh_replay.blsh_capture_runs%rowtype; v_next integer;
begin
  select * into v_run from blsh_replay.blsh_capture_runs as r where r.run_id = p_run_id and r.state = 'claimed' for update;
  if v_run.run_id is null then raise exception 'BLSH capture run is not claimed'; end if;
  if p_path is null or pg_catalog.left(p_path, 58) <> 'native-v6/' || v_run.source_date::text || '/' || v_run.run_id::text || '/' then
    raise exception 'BLSH capture object path is not this run''s';
  end if;
  select pg_catalog.count(*) + 1 into v_next from blsh_replay.blsh_capture_objects as o where o.run_id = p_run_id;
  if p_ordinal <> v_next then raise exception 'BLSH capture object ordinal is not contiguous'; end if;
  if exists (select 1 from blsh_replay.blsh_capture_objects as o where o.run_id = p_run_id and o.path like '%/MANIFEST.json') then
    raise exception 'BLSH capture manifest is already recorded';
  end if;
  if not exists (select 1 from blsh_replay.storage_objects as s where s.bucket_id = 'blsh-native-packets' and s.name = p_path
                 and (s.metadata ->> 'size')::bigint = p_bytes) then
    raise exception 'BLSH capture object is missing from storage or has another size';
  end if;
  insert into blsh_replay.blsh_capture_objects (run_id, ordinal, path, sha256, bytes) values (p_run_id, p_ordinal, p_path, p_sha256, p_bytes);
  return true;
end $$;

-- Closes a claimed run once. A complete or no_slate close needs the recorded MANIFEST.json as
-- the last object, with the stated sha256. abandoned_uncertain is the watchdog's alone.
create function blsh_replay.blsh_capture_close_v1(p_run_id uuid, p_state text, p_reason text, p_manifest_sha256 text)
returns boolean language plpgsql security definer set search_path = '' as $$
declare v_last blsh_replay.blsh_capture_objects%rowtype;
begin
  if p_state not in ('packet_complete_pending_review', 'no_slate', 'refused_schedule', 'failed') then raise exception 'BLSH capture close state is invalid'; end if;
  perform 1 from blsh_replay.blsh_capture_runs as r where r.run_id = p_run_id and r.state = 'claimed' for update;
  if not found then raise exception 'BLSH capture run is not claimed'; end if;
  if p_state in ('packet_complete_pending_review', 'no_slate') then
    select * into v_last from blsh_replay.blsh_capture_objects as o where o.run_id = p_run_id order by o.ordinal desc limit 1;
    if v_last.path is null or v_last.path not like '%/MANIFEST.json' or v_last.sha256 is distinct from p_manifest_sha256 or p_reason is not null then
      raise exception 'BLSH capture completion needs the recorded manifest last';
    end if;
  elsif p_manifest_sha256 is not null or p_reason is null then
    raise exception 'BLSH capture failure needs a reason and no manifest';
  end if;
  update blsh_replay.blsh_capture_runs set state = p_state, reason = p_reason, closed_at = pg_catalog.clock_timestamp(), manifest_sha256 = p_manifest_sha256
  where run_id = p_run_id;
  return true;
end $$;

-- Watchdog part 1 (12:50Z): marks runs claimed for more than 10 minutes abandoned_uncertain.
-- Their intent rows say which admission/NST pairs may have been consumed. Nothing is re-run.
create function blsh_replay.blsh_capture_watchdog_v1() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_marked integer;
begin
  update blsh_replay.blsh_capture_runs
  set state = 'abandoned_uncertain', reason = 'watchdog_claimed_over_10_minutes', closed_at = pg_catalog.clock_timestamp()
  where state = 'claimed' and claimed_at < pg_catalog.clock_timestamp() - interval '10 minutes';
  get diagnostics v_marked = row_count;
  return pg_catalog.jsonb_build_object('abandoned', v_marked);
end $$;

-- Watchdog part 2 (12:52Z, a separate job so part 1 is never rolled back): raises, so the
-- pg_cron run fails visibly, when yesterday's regular-season slate has no closed run, or
-- when that run ended in anything other than a complete packet or no_slate.
create function blsh_replay.blsh_capture_watchdog_assert_v1(p_today date default (pg_catalog.now() at time zone 'UTC')::date)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_day date := p_today - 1; v_games integer; v_state text; v_enabled boolean := blsh_replay.blsh_capture_enabled_v1();
begin
  select pg_catalog.count(*) into v_games from blsh_replay.games as g where g.date = v_day and g.type = 2;
  select r.state into v_state from blsh_replay.blsh_capture_runs as r where r.pipeline = 'native-v6' and r.source_date = v_day;
  if v_enabled and v_games > 0 and v_state is null then raise exception 'BLSH capture missing for %', v_day; end if;
  if v_state is not null and v_state not in ('packet_complete_pending_review', 'no_slate') then
    raise exception 'BLSH capture for % ended %', v_day, v_state;
  end if;
  -- no_slate means the official schedule listed no game for D; games disagreeing is an alert.
  if v_state = 'no_slate' and v_games > 0 then raise exception 'BLSH capture for % was no_slate but games lists % games', v_day, v_games; end if;
  return pg_catalog.jsonb_build_object('sourceDate', v_day, 'games', v_games, 'state', v_state, 'enabled', v_enabled);
end $$;

-- Marks a run to keep past the 45-day retention (a conversion or acceptance references it).
create function blsh_replay.blsh_capture_keep_v1(p_run_id uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  update blsh_replay.blsh_capture_runs set keep = true where run_id = p_run_id;
  return found;
end $$;

-- Retention, step 1 of 3 (owner only): list the Storage paths of closed, not-kept, not-yet-pruned runs
-- older than 45 days. Step 2 deletes those bytes through the Storage API (outside SQL). Step 3 marks
-- each run pruned, and refuses while any of its bytes remain. Rows are never deleted. Never scheduled.
create function blsh_replay.blsh_capture_retention_v1(p_before date)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if p_before > (pg_catalog.now() at time zone 'UTC')::date - 45 then raise exception 'BLSH capture retention keeps 45 days'; end if;
  return (select pg_catalog.jsonb_build_object('before', p_before, 'paths', coalesce(pg_catalog.jsonb_agg(o.path order by o.path), '[]'::jsonb))
          from blsh_replay.blsh_capture_objects as o join blsh_replay.blsh_capture_runs as r using (run_id)
          where r.source_date < p_before and r.state <> 'claimed' and not r.keep and r.pruned_at is null);
end $$;

create function blsh_replay.blsh_capture_mark_pruned_v1(p_run_id uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
declare v_prefix text;
begin
  select 'native-v6/' || r.source_date::text || '/' || r.run_id::text || '/' into v_prefix
  from blsh_replay.blsh_capture_runs as r where r.run_id = p_run_id and r.state <> 'claimed' and not r.keep and r.pruned_at is null
    and r.source_date < (pg_catalog.now() at time zone 'UTC')::date - 45;
  if v_prefix is null then raise exception 'BLSH capture run is not eligible for pruning'; end if;
  if exists (select 1 from blsh_replay.storage_objects as s where s.bucket_id = 'blsh-native-packets' and pg_catalog.left(s.name, 58) = v_prefix) then
    raise exception 'BLSH capture bytes must be deleted from Storage first';
  end if;
  update blsh_replay.blsh_capture_runs set pruned_at = pg_catalog.clock_timestamp() where run_id = p_run_id;
  return true;
end $$;

revoke all on function blsh_replay.blsh_capture_guard_v1(), blsh_replay.blsh_capture_enabled_v1(), blsh_replay.blsh_capture_claim_v1(text, date, jsonb),
  blsh_replay.blsh_capture_intent_v1(uuid, text, text[]), blsh_replay.blsh_capture_object_v1(uuid, integer, text, text, integer),
  blsh_replay.blsh_capture_close_v1(uuid, text, text, text), blsh_replay.blsh_capture_watchdog_v1(), blsh_replay.blsh_capture_watchdog_assert_v1(date),
  blsh_replay.blsh_capture_keep_v1(uuid), blsh_replay.blsh_capture_retention_v1(date), blsh_replay.blsh_capture_mark_pruned_v1(uuid)
  from public, anon, authenticated;

-- blsh_capture_retention_v1 and blsh_capture_mark_pruned_v1 stay owner-only (no grant): run from the SQL editor.

-- ===== 20261116000100_blsh_request_context_v1.sql (retargeted) =====
-- BLSH daily request/context read v1 (Chef decision 3, 2026-11-15; DESIGN.md §5 step 3).
-- FILE ONLY: drafted offline, never applied by the drafting lane. Its caller stays human-gated
-- until this function is independently reviewed, approved by TJ and applied.
--
-- One narrow SECURITY DEFINER read, executable only by service_role, that returns exactly the
-- rows the request reader (tasks/artifacts/blsh-request-reader-20261111, scope d84a9547) reads:
--   - key seal: wgo_skater_stats ids for season 20262027, dates [p_date_from, p_event_through], id order;
--   - per WGO row, the reader's 4-element group: [wgo row, linked NST individual rows,
--     linked NST on-ice rows, linked games rows], each linked list id-ordered with LIMIT 9
--     (the client refuses more than 8), columns exactly as COLUMNS.json c14231f0... lists them.
-- A STABLE function runs every query on the calling statement's snapshot, so the result is one
-- atomic snapshot, like the reader's REPEATABLE READ READ ONLY transaction. It writes nothing.
-- Bounds (the reader's): <= 10,000 WGO rows (refused at 10,001), <= 8 MiB of JSON, a date span
-- of at most 28 days inside the 2026-27 season. statement_timeout is the caller's (PostgREST).

create function blsh_replay.blsh_request_context_v1(p_date_from date, p_event_through date)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  v_ids integer[];
  v_rows jsonb;
  v_out jsonb;
begin
  if p_date_from is null or p_event_through is null or p_date_from > p_event_through
     or p_date_from < date '2026-07-01' or p_event_through > date '2027-06-30'
     or p_event_through - p_date_from > 28 then
    raise exception 'BLSH_REQUEST_CONTEXT_SCOPE_INVALID';
  end if;
  select coalesce(pg_catalog.array_agg(k.id order by k.id), '{}') into v_ids from (
    select w.id from blsh_replay.wgo_skater_stats as w
    where w.season_id = 20262027 and w.date between p_date_from and p_event_through
    order by w.id limit 10001) as k;
  if pg_catalog.cardinality(v_ids) > 10000 then raise exception 'BLSH_REQUEST_CONTEXT_ROW_BOUND'; end if;
  select coalesce(pg_catalog.jsonb_agg(s.row order by s.id), '[]'::jsonb) into v_rows from (
    select w.id, pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_array(w."id",w."player_id",w."game_id",w."season_id",w."date",w."player_name",w."team_abbrev",w."position_code",w."games_played",w."toi_per_game",w."es_toi_per_game",w."pp_toi_per_game",w."goals",w."assists",w."pp_points",w."shots",w."hits",w."blocked_shots",w."total_primary_assists",w."total_secondary_assists",w."penalties_drawn",w."penalties",w."total_fow",w."total_fol",w."sat_for",w."sat_against",w."es_goals_for",w."pp_goals_for",w."sh_goals_for",w."es_goals_against",w."pp_goals_against",w."sh_goals_against",w."points"),
      (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(n."id",n."player_id",n."season",n."date_scraped",n."gp",n."toi",n."ixg",n."goals",n."shots") order by n.id), '[]'::jsonb)
         from (select * from blsh_replay.nst_gamelog_as_counts as x where x.player_id = w.player_id and x.date_scraped = w.date and x.season = 20262027 order by x.id limit 9) as n),
      (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(n."id",n."player_id",n."season",n."date_scraped",n."gp",n."toi",n."xgf",n."xga") order by n.id), '[]'::jsonb)
         from (select * from blsh_replay.nst_gamelog_as_counts_oi as x where x.player_id = w.player_id and x.date_scraped = w.date and x.season = 20262027 order by x.id limit 9) as n),
      (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(g."id",g."seasonId",g."date",g."type") order by g.id), '[]'::jsonb)
         from (select * from blsh_replay.games as x where x.id = w.game_id and x."seasonId" = 20262027 order by x.id limit 9) as g)
    ) as row
    from blsh_replay.wgo_skater_stats as w
    where w.id = any (v_ids) and w.season_id = 20262027 and w.date between p_date_from and p_event_through) as s;
  v_out := pg_catalog.jsonb_build_object(
    'version', 'fhfh.blsh.request-context.v1',
    'seasonId', 20262027,
    'dateFrom', p_date_from,
    'eventThroughDate', p_event_through,
    'snapshotUTC', pg_catalog.transaction_timestamp(),
    'statementUTC', pg_catalog.statement_timestamp(),
    'columnsSHA256', 'c14231f0e62595eed0cb37175360cab33e4731e48a520f22f4bf494e0c127750',
    'keySeal', pg_catalog.jsonb_build_object('ids', pg_catalog.to_jsonb(v_ids), 'rows', pg_catalog.cardinality(v_ids)),
    'rows', v_rows);
  if pg_catalog.octet_length(v_out::text) > 8388608 then raise exception 'BLSH_REQUEST_CONTEXT_BYTE_BOUND'; end if;
  return v_out;
end $$;

revoke all on function blsh_replay.blsh_request_context_v1(date, date) from public, anon, authenticated;


-- ===== 20261118131414_blsh_request_context_custody.sql (retargeted) =====
-- Independent one-shot ledger for the human-gated request/context reader.
-- Storage bodies are hashed by the caller. SQL verifies upload sizes and the exact UTF-8 manifest.

create table blsh_replay.blsh_context_runs (
  run_id uuid primary key default gen_random_uuid(),
  source_date date not null unique,
  native_run_id uuid not null unique references blsh_replay.blsh_capture_runs(run_id),
  native_manifest_sha256 text not null check (native_manifest_sha256 ~ '^[0-9a-f]{64}$'),
  claimed_at timestamptz not null default clock_timestamp(),
  state text not null default 'claimed' check (state in ('claimed','packet_complete_pending_review','failed')),
  closed_at timestamptz,
  reason text check (reason ~ '^[a-z][a-z0-9_:]{2,100}$'),
  manifest_sha256 text check (manifest_sha256 ~ '^[0-9a-f]{64}$'),
  check ((state = 'claimed') = (closed_at is null)),
  check ((state = 'failed') = (reason is not null)),
  check ((state = 'packet_complete_pending_review') = (manifest_sha256 is not null))
);
create table blsh_replay.blsh_context_objects (
  run_id uuid not null references blsh_replay.blsh_context_runs(run_id),
  ordinal integer not null check (ordinal between 1 and 8),
  path text not null unique,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  bytes integer not null check (bytes between 1 and 33554432),
  written_at timestamptz not null default clock_timestamp(),
  primary key (run_id, ordinal)
);
alter table blsh_replay.blsh_context_runs enable row level security;
alter table blsh_replay.blsh_context_objects enable row level security;
revoke all on blsh_replay.blsh_context_runs, blsh_replay.blsh_context_objects from public, anon, authenticated;


create function blsh_replay.blsh_context_guard_v1() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op <> 'UPDATE' or tg_table_name <> 'blsh_context_runs' then raise exception 'context_ledger_immutable'; end if;
  if old.state <> 'claimed' or new.state = 'claimed' or
     (new.run_id, new.source_date, new.native_run_id, new.native_manifest_sha256, new.claimed_at) is distinct from
     (old.run_id, old.source_date, old.native_run_id, old.native_manifest_sha256, old.claimed_at) then
    raise exception 'context_run_immutable';
  end if;
  return new;
end $$;
create trigger blsh_context_runs_guard before update or delete on blsh_replay.blsh_context_runs
  for each row execute function blsh_replay.blsh_context_guard_v1();
create trigger blsh_context_objects_guard before update or delete on blsh_replay.blsh_context_objects
  for each row execute function blsh_replay.blsh_context_guard_v1();
create trigger blsh_context_runs_no_truncate before truncate on blsh_replay.blsh_context_runs
  for each statement execute function blsh_replay.blsh_context_guard_v1();
create trigger blsh_context_objects_no_truncate before truncate on blsh_replay.blsh_context_objects
  for each statement execute function blsh_replay.blsh_context_guard_v1();

