  if exists (select from blsh_replay.fixture_files where encode(sha256(bytes), 'hex') <> sha256) then raise exception 'fixture_hash_mismatch'; end if;
end $$;
create table blsh_replay.receipts (key text primary key check (key ~ '^[a-z0-9-]{1,64}$'), receipt jsonb not null,
  written_at timestamptz not null default clock_timestamp());

-- Sandbox storage RPCs (x-upsert false semantics: an existing object is never replaced).
create function blsh_replay.storage_put_v1(p_bucket text, p_name text, p_mime text, p_b64 text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare b blsh_replay.storage_buckets%rowtype; v bytea := decode(p_b64, 'base64');
begin
  select * into b from blsh_replay.storage_buckets where id = p_bucket;
  if b.id is null then raise exception 'replay_bucket_not_found'; end if;
  if octet_length(v) > b.file_size_limit or not (p_mime = any (b.allowed_mime_types)) then raise exception 'replay_payload_refused'; end if;
  insert into blsh_replay.storage_objects (bucket_id, name, metadata, bytes)
    values (p_bucket, p_name, jsonb_build_object('size', octet_length(v), 'mimetype', p_mime), v);
  return true;
end $$;
create function blsh_replay.storage_get_v1(p_bucket text, p_name text) returns text
language sql stable security definer set search_path = '' as $$
  select encode(o.bytes, 'base64') from blsh_replay.storage_objects o where o.bucket_id = p_bucket and o.name = p_name
$$;
create function blsh_replay.fixture_v1() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('files', jsonb_agg(jsonb_build_object('path', f.path, 'sha256', f.sha256, 'b64', encode(f.bytes, 'base64')) order by f.path))
  from blsh_replay.fixture_files f
$$;
create function blsh_replay.export_v1(p_source_date date) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'native', (select jsonb_build_object('run', to_jsonb(r), 'objects', (select jsonb_agg(to_jsonb(o) || jsonb_build_object('b64',
        (select encode(s.bytes, 'base64') from blsh_replay.storage_objects s where s.bucket_id = 'blsh-native-packets' and s.name = o.path)) order by o.ordinal)
        from blsh_replay.blsh_capture_objects o where o.run_id = r.run_id))
      from blsh_replay.blsh_capture_runs r where r.pipeline = 'native-v6' and r.source_date = p_source_date),
    'context', (select jsonb_build_object('run', to_jsonb(c), 'objects', (select jsonb_agg(to_jsonb(o) || jsonb_build_object('b64',
        (select encode(s.bytes, 'base64') from blsh_replay.storage_objects s where s.bucket_id = 'blsh-request-context' and s.name = o.path)) order by o.ordinal)
        from blsh_replay.blsh_context_objects o where o.run_id = c.run_id))
      from blsh_replay.blsh_context_runs c where c.source_date = p_source_date))
$$;
create function blsh_replay.receipt_put_v1(p_key text, p_receipt jsonb) returns boolean
language plpgsql security definer set search_path = '' as $$
declare v text;
begin
  insert into blsh_replay.receipts (key, receipt) values (p_key, p_receipt) on conflict (key) do nothing returning key into v;
  return v is not null;
end $$;
create function blsh_replay.receipt_get_v1(p_key text) returns jsonb
language sql stable security definer set search_path = '' as $$ select r.receipt from blsh_replay.receipts r where r.key = p_key $$;
revoke all on all tables in schema blsh_replay from public;
revoke all on all functions in schema blsh_replay from public;

